"use server";

/**
 * Creates an organization with the caller as owner.
 *
 * Owner D. There is no actor *before* the org exists, so this action resolves
 * the session principal first and only calls `getActor()` afterwards — against
 * the slug of the organization it just created — to confirm the owner
 * membership landed.
 *
 * Must call (do not reimplement): createOrganizationSchema, getActor,
 * toActionResult
 */

import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
import { getActor } from "@/lib/actor";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import { createOrganizationSchema } from "@/schemas/organization";
import { createOrganization } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";
import { revalidatePath } from "next/cache";

export async function createOrganizationAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  const parsed = createOrganizationSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const principal = await getSessionPrincipal();
    if (principal === null) {
      throw new UnauthorizedActionError();
    }

    const organization = await createOrganization(principal.userId, parsed.data);

    // The owner membership is written by the service; resolving the actor here
    // fails loudly if it was not, rather than leaving an org nobody can open.
    await getActor(organization.slug);

    revalidatePath("/orgs");
    return { ok: true, data: organization, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}
"use client";

/**
 * Client form bound to `registerSchema`.
 *
 * Owner D. `registerSchema` carries the password policy *and* the
 * confirm-password refinement, so running it here means the "passwords do not
 * match" message is produced by the same rule the server applies.
 *
 * Must call (do not reimplement): registerSchema
 */

import { useActionState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { registerAction } from "@/actions/auth/register";
import { fieldErrorsFromZod } from "@/lib/errors";
import { registerSchema } from "@/schemas/auth";
import type { ActionResult } from "@/types/api";
import type { SessionPrincipal } from "@/types/member";

type RegisterState = ActionResult<SessionPrincipal> | null;

export function RegisterForm() {
  const router = useRouter();

  const [state, submit, pending] = useActionState<RegisterState, FormData>(
    async (_previous, formData) => {
      const parsed = registerSchema.safeParse({
        name: String(formData.get("name") ?? ""),
        email: String(formData.get("email") ?? ""),
        password: String(formData.get("password") ?? ""),
        confirmPassword: String(formData.get("confirmPassword") ?? ""),
        acceptTerms: formData.get("acceptTerms") === "on",
      });

      if (!parsed.success) {
        return {
          ok: false,
          error: {
            code: "validation_failed",
            message: "Check the fields below.",
            fieldErrors: fieldErrorsFromZod(parsed.error),
          },
        };
      }

      return registerAction(parsed.data);
    },
    null,
  );

  useEffect(() => {
    if (state?.ok === true) {
      router.push("/orgs");
    }
  }, [state, router]);

  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};

  return (
    <form action={submit} className="space-y-5">
      <h1 className="text-lg font-semibold">Create your organization</h1>

      {state?.ok === false && state.error.code !== "validation_failed" ? (
        <p role="alert" className="rounded bg-rose-50 px-3 py-2 text-sm text-rose-700">
          {state.error.message}
        </p>
      ) : null}

      <Field id="name" label="Your name" errors={fieldErrors.name}>
        <input
          id="name"
          name="name"
          autoComplete="name"
          required
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
        />
      </Field>

      <Field id="email" label="Work email" errors={fieldErrors.email}>
        <input
          id="email"
          name="email"
          type="email"
          autoComplete="email"
          required
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
        />
      </Field>

      <Field
        id="password"
        label="Password"
        hint="At least 12 characters, with an upper case letter and a digit."
        errors={fieldErrors.password}
      >
        <input
          id="password"
          name="password"
          type="password"
          autoComplete="new-password"
          required
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
        />
      </Field>

      <Field
        id="confirmPassword"
        label="Confirm password"
        errors={fieldErrors.confirmPassword}
      >
        <input
          id="confirmPassword"
          name="confirmPassword"
          type="password"
          autoComplete="new-password"
          required
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
        />
      </Field>

      <label className="flex items-start gap-2 text-sm text-slate-600">
        <input type="checkbox" name="acceptTerms" className="mt-1" />
        I accept the terms of service.
      </label>
      {fieldErrors.acceptTerms !== undefined ? (
        <p className="text-xs text-rose-600">{fieldErrors.acceptTerms[0]}</p>
      ) : null}

      <button
        type="submit"
        disabled={pending}
        className="w-full rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60"
      >
        {pending ? "Creating…" : "Create account"}
      </button>
    </form>
  );
}

function Field(props: {
  id: string;
  label: string;
  hint?: string;
  errors?: readonly string[];
  children: React.ReactNode;
}) {
  return (
    <div className="space-y-1">
      <label htmlFor={props.id} className="text-sm font-medium">
        {props.label}
      </label>
      {props.children}
      {props.hint !== undefined ? (
        <p className="text-xs text-slate-500">{props.hint}</p>
      ) : null}
      {props.errors !== undefined && props.errors.length > 0 ? (
        <p className="text-xs text-rose-600">{props.errors[0]}</p>
      ) : null}
    </div>
  );
}
  return row ? toMember(row) : null;
}

/** Cursor-paged member list joined with the user record the UI renders. */
export async function listMembers(
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  const db = getDb();
  const sort = { sortColumn: members.createdAt, idColumn: members.id };

  const filters = compact(
    orgPredicate(members.orgId, input.orgId),
    liveMemberPredicate(),
    input.role === undefined ? undefined : eq(members.role, input.role),
    input.status === undefined ? undefined : eq(members.status, input.status),
    input.query === undefined
      ? undefined
      : or(
          like(users.name, `%${input.query}%`),
          like(users.email, `%${input.query}%`),
        ),
  );

  const total = db
    .select({ value: count() })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters))
    .get();

  const rows = db
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(members.createdAt), desc(members.id))
